SELECT 

WHERE d.student_id = #{studentId} AND d.deleted = 0
AND d.aid_type != 'need'
AND d.status = #{status}
ORDER BY d.created_at DESC, d.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT
WHERE d.deleted = 0 AND d.aid_type != 'need'
ORDER BY FIELD(d.status, 'pending') DESC, d.created_at DESC, d.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT d.status AS status, COUNT(*) AS cnt

WHERE d.deleted = 0
AND d.aid_type != 'need'
AND d.student_id = #{studentId}
AND sp.counselor_id = #{scopeCounselorId}
GROUP BY d.status

SELECT COUNT(*)
FROM aid_application
WHERE deleted = 0
  AND status IN ('pending', 'approved')
  AND student_id = #{studentId}
  AND aid_type = #{aidType}
  AND academic_year = #{academicYear}

